<?php if (!defined('SGCE_APP')) { exit; } ?>
<div class="card MainCard"><div class="card-header bg-white border-0 p-4"><div class="d-flex justify-content-between align-items-center flex-wrap gap-3"><div><h4 class="fw-bold mb-1">Lista de alumnos</h4><div class="text-muted">Selecciona el estado de asistencia</div></div><div class="badge bg-dark rounded-pill px-4 py-3"><?= (int)count($Alumnos) ?> Alumnos</div></div></div><div class="card-body p-0"><form method="POST"><?= CampoCsrf() ?><input type="hidden" name="asignacion_id" value="<?= (int)$AsignacionId ?>"><input type="hidden" name="Fecha" value="<?= HGlobal($FechaConsulta) ?>"><div class="table-responsive"><table class="table align-middle mb-0 SgceTable SgceAttendanceMobileTable"><thead class="table-light"><tr><th class="ps-4">Alumno</th><th class="text-center SgceAsistenciaEstadoCol">Estado</th></tr></thead><tbody><?php if(empty($Alumnos)): ?><tr><td colspan="2"><?= SgceComponenteTablaVacia('No hay alumnos registrados') ?></td></tr><?php else: foreach($Alumnos as $a): $EstadoActual=$EstadosRegistrados[(int)$a['Id']] ?? 'A'; ?><tr><td class="ps-4"><div class="d-flex align-items-center gap-3"><div class="AlumnoAvatar AlumnoAvatarEmoji"><span class="SgceAlumnoEmoji" aria-hidden="true">🧑‍🎓</span></div><div><div class="AlumnoNombre"><?= HGlobal($a['NombreCompleto']) ?></div></div></div></td><td><select name="estado[<?= (int)$a['Id'] ?>]" class="form-select EstadoSelect"><option value="A" <?= $EstadoActual==='A'?'selected':'' ?>>✅ Asistencia</option><option value="F" <?= $EstadoActual==='F'?'selected':'' ?>>❌ Falta</option><option value="R" <?= $EstadoActual==='R'?'selected':'' ?>>⏰ Retardo</option><option value="J" <?= $EstadoActual==='J'?'selected':'' ?>>📄 Justificante</option></select></td></tr><?php endforeach; endif; ?></tbody></table></div><?php if (!empty($Alumnos)): ?><div class="SgceStickyActions border-top"><button type="submit" name="guardar" id="BtnGuardarAsistenciaVerdeMetalico" class="btn BtnGuardar BtnAsistenciaVerdeMetalico"><span class="me-2" aria-hidden="true">💾</span><?= $YaSeRegistro ? 'Actualizar pase de lista' : 'Guardar pase de lista' ?></button></div><?php endif; ?></form></div></div>
